VALUES ('doc-09-mitre-attack-p0-22458', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2021-03-02T18:16:41.063Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[AppleJeus](https://attack.mitre.org/software/S0584) has deleted the MSI file after installation.(Citation: CISA AppleJeus Feb 2021)", "external_references": [{"description": "Cybersecurity and Infrastructure Security Agency. (2021, February 21). AppleJeus: Analysis of North Korea’s Cryptocurrency Malware. Retrieved March 1, 2021.", "source_name": "CISA AppleJeus Feb 2021", "url": "https://us-cert.cisa.gov/ncas/alerts/aa21-048a"}], "id": "relationship--0a068253-0c11-4ba7-bac4-1290e5f50960", "modified": "2026-04-29T14:23:05.917Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--e2d34c63-6f5a-41f5-86a2-e2380f27f858", "spec_version": "2.1", "target_ref": "attack-pattern--d63a3fb8-9452-4e9d-a60a-54be68d5998c", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-22458', 0, 69, '09-mitre-attack', 'retrieved', '5046622A7554A0C7AE9A8FBD533A74EED633E94BBD8952AE0867728D9E9ECF0A', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
