VALUES ('doc-09-mitre-attack-p0-22459', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2022-09-28T17:46:18.553Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "During [AppleJeus](https://attack.mitre.org/software/S0584)''s installation process, it uses `postinstall` scripts to extract a hidden plist from the application''s `/Resources` folder and execute the `plist` file as a [Launch Daemon](https://attack.mitre.org/techniques/T1543/004) with elevated permissions.(Citation: ObjectiveSee AppleJeus 2019)", "external_references": [{"description": "Patrick Wardle. (2019, October 12). Pass the AppleJeus. Retrieved September 28, 2022.", "source_name": "ObjectiveSee AppleJeus 2019", "url": "https://objective-see.org/blog/blog_0x49.html"}], "id": "relationship--0e078567-e5b6-45b6-a1c7-3b1f8ac3e2a8", "modified": "2026-04-29T14:23:05.922Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--e2d34c63-6f5a-41f5-86a2-e2380f27f858", "spec_version": "2.1", "target_ref": "attack-pattern--da051493-ae9c-4b1b-9760-c009c46c9b56", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-22459', 0, 82, '09-mitre-attack', 'retrieved', 'FDB8B9A0C2D7C7D38EDF3D04D54F562C6C2EB77E18A3FCAFD93B023E72856A5C', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
