VALUES ('doc-09-mitre-attack-p0-22491', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2022-08-18T15:36:13.631Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[STARWHALE](https://attack.mitre.org/software/S1037) can gather the computer name of an infected host.(Citation: Mandiant UNC3313 Feb 2022)(Citation: DHS CISA AA22-055A MuddyWater February 2022)", "external_references": [{"description": "FBI, CISA, CNMF, NCSC-UK. (2022, February 24). Iranian Government-Sponsored Actors Conduct Cyber Operations Against Global Government and Commercial Networks. Retrieved September 27, 2022.", "source_name": "DHS CISA AA22-055A MuddyWater February 2022", "url": "https://www.cisa.gov/uscert/ncas/alerts/aa22-055a"}, {"description": "Tomcik, R. et al. (2022, February 24). Left On Read: Telegram Malware Spotted in Latest Iranian Cyber Espionage Activity. Retrieved August 18, 2022.", "source_name": "Mandiant UNC3313 Feb 2022", "url": "https://www.mandiant.com/resources/telegram-malware-iranian-espionage"}], "id": "relationship--12168524-c6cf-4b8f-b114-7b10b06b8f32", "modified": "2026-04-29T14:23:05.929Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--e355fc84-6f3c-4888-8e0a-d7fa9c378532", "spec_version": "2.1", "target_ref": "attack-pattern--354a7f88-63fb-41b5-a801-ce3b377b36f1", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-22491', 0, 114, '09-mitre-attack', 'retrieved', '6418EE280871635E572BC4A07BF82DBABB5AAE28EAD95D990C9BEE6941D9DC1F', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
