VALUES ('doc-09-mitre-attack-p0-22511', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2021-01-04T20:42:22.133Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Industroyer](https://attack.mitre.org/software/S0604)’s data wiper module clears registry keys and overwrites both ICS configuration and Windows files.(Citation: Dragos Crashoverride 2017)", "external_references": [{"description": "Dragos Inc.. (2017, June 13). CRASHOVERRIDE Analysis of the Threat to Electric Grid Operations. Retrieved December 18, 2020.", "source_name": "Dragos Crashoverride 2017", "url": "https://dragos.com/blog/crashoverride/CrashOverride-01.pdf"}], "id": "relationship--16873550-3105-4ce5-92fc-7b8127e47b5d", "modified": "2026-04-29T14:23:05.935Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--e401d4fe-f0c9-44f0-98e6-f93487678808", "spec_version": "2.1", "target_ref": "attack-pattern--d45a3d09-b3cf-48f4-9f0f-f521ee5cb05c", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-22511', 0, 73, '09-mitre-attack', 'retrieved', '879860853C4D78DFA38E13183820243E4B07AD8C5255F24E3DDF530C9A9E8EA8', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
