VALUES ('doc-09-mitre-attack-p0-22535', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2026-04-22T22:43:45.782Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[LazyWiper](https://attack.mitre.org/software/S9039) has overwritten files with pseudorandom 32‑byte sequences written at 16‑byte intervals making the file unrecoverable.(Citation: CERT Polska)", "external_references": [{"description": "CERT Polska. (2026, January 30). Energy Sector Incident Report – 29 December. Retrieved April 22, 2026.", "source_name": "CERT Polska", "url": "https://cert.pl/uploads/docs/CERT_Polska_Energy_Sector_Incident_Report_2025.pdf"}], "id": "relationship--c576e2b9-dc3f-4c4a-8465-41e92a93c90a", "modified": "2026-04-29T14:23:06.195Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--e4160979-b9bc-4f58-acbe-1d921ebbc122", "spec_version": "2.1", "target_ref": "attack-pattern--d45a3d09-b3cf-48f4-9f0f-f521ee5cb05c", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-22535', 0, 70, '09-mitre-attack', 'retrieved', '200B940C92B8DD97B00C016A3C2D31C05F8C9570F0A8A961211FA89D18F5948C', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
