VALUES ('doc-09-mitre-attack-p0-22558', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2017-12-14T16:46:06.044Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[CozyCar](https://attack.mitre.org/software/S0046) uses Twitter as a backup C2 channel to Twitter accounts specified in its configuration file.(Citation: F-Secure CozyDuke)", "external_references": [{"description": "F-Secure Labs. (2015, April 22). CozyDuke: Malware Analysis. Retrieved December 10, 2015.", "source_name": "F-Secure CozyDuke", "url": "https://www.f-secure.com/documents/996508/1030745/CozyDuke"}], "id": "relationship--233d1a32-f826-4705-a535-806edee8a5aa", "modified": "2026-04-29T14:23:05.953Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--e6ef745b-077f-42e1-a37d-29eecff9c754", "spec_version": "2.1", "target_ref": "attack-pattern--be055942-6e63-49d7-9fa1-9cb7d8a8f3f4", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-22558', 0, 66, '09-mitre-attack', 'retrieved', '144B7A78FC5FA74C83C0AC09BAA6F8193F66AE355D5C8CE95F90AE3C008B312A', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
