VALUES ('doc-09-mitre-attack-p0-22562', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2020-03-19T22:40:09.367Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[CozyCar](https://attack.mitre.org/software/S0046) has executed [Mimikatz](https://attack.mitre.org/software/S0002) to harvest stored credentials from the victim and further victim penetration.(Citation: F-Secure CozyDuke)", "external_references": [{"description": "F-Secure Labs. (2015, April 22). CozyDuke: Malware Analysis. Retrieved December 10, 2015.", "source_name": "F-Secure CozyDuke", "url": "https://www.f-secure.com/documents/996508/1030745/CozyDuke"}], "id": "relationship--78c889da-e1e2-4230-a91d-9934627fecf6", "modified": "2026-04-29T14:23:06.090Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--e6ef745b-077f-42e1-a37d-29eecff9c754", "spec_version": "2.1", "target_ref": "attack-pattern--65f2d882-3f41-4d48-8a06-29af77ec9f90", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-22562', 0, 65, '09-mitre-attack', 'retrieved', '88D0C5266E143762F88AE9EC924F3144E90657B6114B547B606085641873D3CA', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
