INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-09-mitre-attack-p0-22563', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2019-04-24T13:32:25.647Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Some versions of [CozyCar](https://attack.mitre.org/software/S0046) will check to ensure it is not being executed inside a virtual machine or a known malware analysis sandbox environment. If it detects that it is, it will exit.(Citation: F-Secure CozyDuke)", "external_references": [{"description": "F-Secure Labs. (2015, April 22). CozyDuke: Malware Analysis. Retrieved December 10, 2015.", "source_name": "F-Secure CozyDuke", "url": "https://www.f-secure.com/documents/996508/1030745/CozyDuke"}], "id": "relationship--8f88490e-346b-4462-b077-0211707c21a3", "modified": "2026-04-29T14:23:06.121Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--e6ef745b-077f-42e1-a37d-29eecff9c754", "spec_version": "2.1", "target_ref": "attack-pattern--82caa33e-d11a-433a-94ea-9b5a5fbef81d", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-22563', 0, 83, '09-mitre-attack', 'retrieved', '3ABFE54C35092EF01DA0A1733CBB22EA5BE300A8D24DC7C5E6376A867A8026E0', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
