VALUES ('doc-09-mitre-attack-p0-22566', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2018-01-16T16:13:52.465Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "The [CozyCar](https://attack.mitre.org/software/S0046) dropper has masqueraded a copy of the infected system''s rundll32.exe executable that was moved to the malware''s install directory and renamed according to a predefined configuration file.(Citation: F-Secure CozyDuke)", "external_references": [{"description": "F-Secure Labs. (2015, April 22). CozyDuke: Malware Analysis. Retrieved December 10, 2015.", "source_name": "F-Secure CozyDuke", "url": "https://www.f-secure.com/documents/996508/1030745/CozyDuke"}], "id": "relationship--a4a49b56-e220-4a81-a0da-43b63c012cfe", "modified": "2026-04-29T14:23:06.149Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--e6ef745b-077f-42e1-a37d-29eecff9c754", "spec_version": "2.1", "target_ref": "attack-pattern--bd5b58a4-a52d-4a29-bc0d-3f1d3968eb6b", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-22566', 0, 79, '09-mitre-attack', 'retrieved', 'C02B4C140C46F547B800E1874655DBC3C67CA7372C6A3C6281AED65D5BFC6F31', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
