VALUES ('doc-09-mitre-attack-p0-22569', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2022-06-14T15:35:39.078Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Variants of [Kevin](https://attack.mitre.org/software/S1020) can communicate over DNS through queries to the server for constructed domain names with embedded information.(Citation: Kaspersky Lyceum October 2021)", "external_references": [{"description": "Kayal, A. et al. (2021, October). LYCEUM REBORN: COUNTERINTELLIGENCE IN THE MIDDLE EAST. Retrieved June 14, 2022.", "source_name": "Kaspersky Lyceum October 2021", "url": "https://vblocalhost.com/uploads/VB2021-Kayal-etal.pdf"}], "id": "relationship--11c19a8d-fd24-4c59-9a5f-4910f5471e71", "modified": "2026-04-29T14:23:05.928Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--e7863f5d-cb6a-4f81-8804-0a635eec160a", "spec_version": "2.1", "target_ref": "attack-pattern--1996eef1-ced3-4d7f-bf94-33298cabbf72", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-22569', 0, 78, '09-mitre-attack', 'retrieved', 'C96919C4F5A2DC2BFAB4A1A144109333D41FE45503BA67E993673804F87BA42B', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
