VALUES ('doc-09-mitre-attack-p0-22591', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2020-05-19T17:32:26.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": " [Agent Tesla](https://attack.mitre.org/software/S0331) has the ability to perform anti-sandboxing and anti-virtualization checks.(Citation: Malwarebytes Agent Tesla April 2020)", "external_references": [{"description": "Jazi, H. (2020, April 16). New AgentTesla variant steals WiFi credentials. Retrieved May 19, 2020.", "source_name": "Malwarebytes Agent Tesla April 2020", "url": "https://blog.malwarebytes.com/threat-analysis/2020/04/new-agenttesla-variant-steals-wifi-credentials/"}], "id": "relationship--061f0d25-40fd-440a-b7e8-54ad0209f5f4", "modified": "2026-04-29T14:23:05.911Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--e7a5229f-05eb-440e-b982-9a6d2b2b87c8", "spec_version": "2.1", "target_ref": "attack-pattern--82caa33e-d11a-433a-94ea-9b5a5fbef81d", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-22591', 0, 71, '09-mitre-attack', 'retrieved', 'F1D82B24FF26381AA8F5CEB8338130D8B236C0035849728197DCB5FD67166BA1', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
