VALUES ('doc-09-mitre-attack-p0-22674', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-07-21T20:12:41.549Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[StarProxy](https://attack.mitre.org/software/S1227) has utilized TLS record headers in network packets to impersonate various versions of TLS protocols to blend in with legitimate network traffic. [StarProxy](https://attack.mitre.org/software/S1227) used FakeTLS to communicate with its C2 server.(Citation: Zscaler)", "external_references": [{"description": "Sudeep Singh. (2025, April 16). Latest Mustang Panda Arsenal: ToneShell and StarProxy | P1. Retrieved July 21, 2025.", "source_name": "Zscaler", "url": "https://www.zscaler.com/blogs/security-research/latest-mustang-panda-arsenal-toneshell-and-starproxy-p1"}], "id": "relationship--354a4208-0d17-47ab-bf0d-8611c5ad23e5", "modified": "2026-04-29T14:23:05.991Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--e91d3543-ca5d-474b-8b20-5a753ebc6e49", "spec_version": "2.1", "target_ref": "attack-pattern--c325b232-d5bc-4dde-a3ec-71f3db9e8adc", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-22674', 0, 86, '09-mitre-attack', 'retrieved', 'DAD7D649B1D488537D1CDDD99ACC90F6FE99516F8BCD8EA6D7DE0FEFB5557AD7', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
