VALUES ('doc-09-mitre-attack-p0-22675', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-07-21T20:13:29.433Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[StarProxy](https://attack.mitre.org/software/S1227) has used native windows API calls such as `GetLocalTime()` to retrieve system data.(Citation: Zscaler)", "external_references": [{"description": "Sudeep Singh. (2025, April 16). Latest Mustang Panda Arsenal: ToneShell and StarProxy | P1. Retrieved July 21, 2025.", "source_name": "Zscaler", "url": "https://www.zscaler.com/blogs/security-research/latest-mustang-panda-arsenal-toneshell-and-starproxy-p1"}], "id": "relationship--62c26c33-a177-4ab6-b070-6157c3528b9e", "modified": "2026-04-29T14:23:06.059Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--e91d3543-ca5d-474b-8b20-5a753ebc6e49", "spec_version": "2.1", "target_ref": "attack-pattern--391d824f-0ef1-47a0-b0ee-c59a75e27670", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-22675', 0, 68, '09-mitre-attack', 'retrieved', '6F72F1032CFCFEF49F33083A3D17AF427622B60493016CDC32F462B16B1D2CEC', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
