VALUES ('doc-09-mitre-attack-p0-22685', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2021-03-18T16:33:07.747Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[ECCENTRICBANDWAGON](https://attack.mitre.org/software/S0593) has stored keystrokes and screenshots within the %temp%\\GoogleChrome , %temp%\\Downloads , and %temp%\\TrendMicroUpdate directories.(Citation: CISA EB Aug 2020)", "external_references": [{"description": "Cybersecurity and Infrastructure Security Agency. (2020, August 26). MAR-10301706-1.v1 - North Korean Remote Access Tool: ECCENTRICBANDWAGON. Retrieved March 18, 2021.", "source_name": "CISA EB Aug 2020", "url": "https://us-cert.cisa.gov/ncas/analysis-reports/ar20-239a"}], "id": "relationship--f8c1f1e4-4580-4ec6-9bc0-6f24214dc273", "modified": "2026-04-29T14:23:06.263Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--e928333f-f3df-4039-9b8b-556c2add0e42", "spec_version": "2.1", "target_ref": "attack-pattern--1c34f7aa-9341-4a48-bfab-af22e51aca6c", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-22685', 0, 77, '09-mitre-attack', 'retrieved', '969FBDC3F6747D16234D08D5D3E98648906553CC7E92958F97DFB1E9C2627463', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
