VALUES ('doc-09-mitre-attack-p0-22823', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2021-09-27T20:31:57.606Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[QakBot](https://attack.mitre.org/software/S0650) can check the compromised host for the presence of multiple executables associated with analysis tools and halt execution if any are found.(Citation: Trend Micro Qakbot May 2020)(Citation: ATT QakBot April 2021)", "external_references": [{"description": "Mendoza, E. et al. (2020, May 25). Qakbot Resurges, Spreads through VBS Files. Retrieved September 27, 2021.", "source_name": "Trend Micro Qakbot May 2020", "url": "https://www.trendmicro.com/vinfo/ph/security/news/cybercrime-and-digital-threats/qakbot-resurges-spreads-through-vbs-files"}, {"description": "Morrow, D. (2021, April 15). The rise of QakBot. Retrieved September 27, 2021.", "source_name": "ATT QakBot April 2021", "url": "https://cybersecurity.att.com/blogs/labs-research/the-rise-of-qakbot"}], "id": "relationship--05d8ec5a-0fc4-4037-913f-4d48e658ee9b", "modified": "2026-04-29T14:23:05.911Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--edc5e045-5401-42bb-ad92-52b5b2ee0de9", "spec_version": "2.1", "target_ref": "attack-pattern--29be378d-262d-4e99-b00d-852d573628e6", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-22823', 0, 109, '09-mitre-attack', 'retrieved', '66258DFF0DE79B3E88F31CF0BE9DC8AE78B415C195EC2EA65B9F9AE9C0930D13', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
