VALUES ('doc-09-mitre-attack-p0-22847', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2021-09-28T15:46:27.084Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[QakBot](https://attack.mitre.org/software/S0650) has gained execution through users opening malicious attachments.(Citation: Trend Micro Qakbot May 2020)(Citation: Kroll Qakbot June 2020)(Citation: Crowdstrike Qakbot October 2020)(Citation: Trend Micro Qakbot December 2020)(Citation: Cyberint Qakbot May 2021)(Citation: ATT QakBot April 2021)(Citation: Kaspersky QakBot September 2021)(Citation: Group IB Ransomware September 2020)(Citation: Deep Instinct Black Basta August 2022)(Citation: Microsoft Ransomware as a Service)", "external_references": [{"description": "CS. (2020, October 7). Duck Hunting with Falcon Complete: A Fowl Banking Trojan Evolves, Part 2. Retrieved September 27, 2021.", "source_name": "Crowdstrike Qakbot October 2020", "url": "https://www.crowdstrike.com/blog/duck-hunting-with-falcon-complete-qakbot-zip-based-campaign/"}, {"description": "Cyberint. (2021, May 25). Qakbot Banking Trojan. Retrieved September 27, 2021.", "source_name": "Cyberint Qakbot May 2021", "url": "https://blog.cyberint.com/qakbot-banking-trojan"}, {"description": "Group IB. (2020, September). LOCK LIKE A PRO. Retrieved November 17, 2024.", "source_name": "Group IB Ransomware September 2020", "url": "https://web.archive.org/web/20220119114433/https://groupib.pathfactory.com/ransomware-reports/prolock_wp"}, {"description": "Kuzmenko, A. et al. (2021, September 2). QakBot technical analysis. Retrieved September 27, 2021.", "source_name": "Kaspersky QakBot September 2021", "url": "https://securelist.com/qakbot-technical-analysis/103931/"}, {"description": "Mendoza, E. et al. (2020, May 25). Qakbot Resurges, Spreads through VBS Files. Retrieved September 27, 2021.", "source_name": "Trend Micro Qakbot May 2020", "url": "https://www.trendmicro.com/vinfo/ph/security/news/cybercrime-and-digital-threats/qakbot-resurges-spreads-through-vbs-files"}, {"description": "Microsoft. (2022, May 9). Ransomware as a service: Understanding the cybercrime gig economy and how to protect yourself. Retrieved March 10, 2023.", "source_name": "Microsoft Ransomware as a Service", "url": "https://www.microsoft.com/en-us/security/blog/2022/05/09/ransomware-as-a-service-understanding-the-cybercrime-gig-economy-and-how-to-protect-yourself/"}, {"description": "Morrow, D. (2021, April 15). The rise of QakBot. Retrieved September 27, 2021.", "source_name": "ATT QakBot April 2021", "url": "https://cybersecurity.att.com/blogs/labs-research/the-rise-of-qakbot"}, {"description": "Sette, N. et al. (2020, June 4). Qakbot Malware Now Exfiltrating Emails for Sophisticated Thread Hijacking Attacks. Retrieved September 27, 2021.", "source_name": "Kroll Qakbot June 2020", "url": "https://www.kroll.com/en/insights/publications/cyber/qakbot-malware-exfiltrating-emails-thread-hijacking-attacks"}, {"description": "Trend Micro. (2020, December 17). QAKBOT: A decade-old malware still with new tricks. Retrieved November 17, 2024.", "source_name": "Trend Micro Qakbot December 2020", "url": "https://success.trendmicro.com/en-US/solution/KA-0011282"}, {"description": "Vilkomir-Preisman, S. (2022, August 18). Beating Black Basta Ransomware. Retrieved March 8, 2023.", "source_name": "Deep Instinct Black Basta August 2022", "url": "https://www.deepinstinct.com/blog/black-basta-ransomware-threat-emergence"}], "id": "relationship--403e9797-7824-4840-87ad-b975023d9199", "modified": "2026-04-29T14:23:06.012Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--edc5e045-5401-42bb-ad92-52b5b2ee0de9", "spec_version": "2.1", "target_ref": "attack-pattern--232b7f21-adf9-4b42-b936-b9d6f7df856e", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_