VALUES ('doc-09-mitre-attack-p0-22931', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2020-08-13T16:51:23.474Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Hancitor](https://attack.mitre.org/software/S0499) has used a macro to check that an ActiveDocument shape object in the lure message is present. If this object is not found, the macro will exit without downloading additional payloads.(Citation: FireEye Hancitor)", "external_references": [{"description": "Anubhav, A., Jallepalli, D. (2016, September 23). Hancitor (AKA Chanitor) observed using multiple attack approaches. Retrieved August 13, 2020.", "source_name": "FireEye Hancitor", "url": "https://www.fireeye.com/blog/threat-research/2016/09/hancitor_aka_chanit.html"}], "id": "relationship--f60f8552-3c43-4b43-ad23-2b00b6172b00", "modified": "2026-04-29T14:23:06.259Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--ef2247bf-8062-404b-894f-d65d00564817", "spec_version": "2.1", "target_ref": "attack-pattern--82caa33e-d11a-433a-94ea-9b5a5fbef81d", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-22931', 0, 89, '09-mitre-attack', 'retrieved', '041C840726B5BE8F1F897D17A725FD0D02AECC25BD57958E0B316E7A986FECFE', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
