VALUES ('doc-09-mitre-attack-p0-22991', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2018-10-17T00:14:20.652Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[jRAT](https://attack.mitre.org/software/S0283)’s Java payload is encrypted with AES.(Citation: jRAT Symantec Aug 2018) Additionally, backdoor files are encrypted using DES as a stream cipher. Later variants of [jRAT](https://attack.mitre.org/software/S0283) also incorporated AV evasion methods such as Java bytecode obfuscation via the commercial Allatori obfuscation tool.(Citation: Symantec Frutas Feb 2013)", "external_references": [{"description": "Sharma, R. (2018, August 15). Revamped jRAT Uses New Anti-Parsing Techniques. Retrieved September 21, 2018.", "source_name": "jRAT Symantec Aug 2018", "url": "https://www.symantec.com/blogs/threat-intelligence/jrat-new-anti-parsing-techniques"}, {"description": "Bingham, J. (2013, February 11). Cross-Platform Frutas RAT Builder and Back Door. Retrieved April 23, 2019.", "source_name": "Symantec Frutas Feb 2013", "url": "https://www.symantec.com/connect/blogs/cross-platform-frutas-rat-builder-and-back-door"}], "id": "relationship--ec2e27c9-71fe-4650-a5b9-1247193c39f6", "modified": "2026-04-29T14:23:06.246Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--efece7e8-e40b-49c2-9f84-c55c5c93d05c", "spec_version": "2.1", "target_ref": "attack-pattern--b3d682b6-98f2-4fb0-aa3b-b4df007ca70a", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-22991', 0, 123, '09-mitre-attack', 'retrieved', '6C6F46775764DFA7D032A6851536F54C1E45B8376AF3263C5BBA743EA03AE697', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRU