VALUES ('doc-09-mitre-attack-p0-23009', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2018-01-16T16:13:52.465Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "A [Helminth](https://attack.mitre.org/software/S0170) VBScript receives a batch script to execute a set of commands in a command prompt.(Citation: Palo Alto OilRig May 2016)", "external_references": [{"description": "Falcone, R. and Lee, B.. (2016, May 26). The OilRig Campaign: Attacks on Saudi Arabian Organizations Deliver Helminth Backdoor. Retrieved May 3, 2017.", "source_name": "Palo Alto OilRig May 2016", "url": "http://researchcenter.paloaltonetworks.com/2016/05/the-oilrig-campaign-attacks-on-saudi-arabian-organizations-deliver-helminth-backdoor/"}], "id": "relationship--cd58d271-9ee2-45d6-9ca3-22ae8da639b5", "modified": "2026-04-29T14:23:06.206Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--eff1a885-6f90-42a1-901f-eef6e7a1905e", "spec_version": "2.1", "target_ref": "attack-pattern--30208d3e-0d6b-43c8-883e-44462a514619", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-23009', 0, 84, '09-mitre-attack', 'retrieved', 'A8EA5377450955492F8E19B72361406AD5DAB567696E24C384DC6594B8D1C2D0', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
