VALUES ('doc-09-mitre-attack-p0-23011', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2018-01-16T16:13:52.465Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Helminth](https://attack.mitre.org/software/S0170) splits data into chunks up to 23 bytes and sends the data in DNS queries to its C2 server.(Citation: Palo Alto OilRig May 2016)", "external_references": [{"description": "Falcone, R. and Lee, B.. (2016, May 26). The OilRig Campaign: Attacks on Saudi Arabian Organizations Deliver Helminth Backdoor. Retrieved May 3, 2017.", "source_name": "Palo Alto OilRig May 2016", "url": "http://researchcenter.paloaltonetworks.com/2016/05/the-oilrig-campaign-attacks-on-saudi-arabian-organizations-deliver-helminth-backdoor/"}], "id": "relationship--f81274dc-2f5b-47f7-b91f-70a4ebdfde95", "modified": "2026-04-29T14:23:06.262Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--eff1a885-6f90-42a1-901f-eef6e7a1905e", "spec_version": "2.1", "target_ref": "attack-pattern--c3888c54-775d-4b2f-b759-75a2ececcbfd", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-23011', 0, 87, '09-mitre-attack', 'retrieved', '32546228D3D28D21612D55A53FA43E6ECBBB615EF99E6270F3F1BB762BE1D302', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
