VALUES ('doc-09-mitre-attack-p0-23013', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2018-01-16T16:13:52.465Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Helminth](https://attack.mitre.org/software/S0170) has checked the local administrators group.(Citation: Unit 42 Playbook Dec 2017)", "external_references": [{"description": "Unit 42. (2017, December 15). Unit 42 Playbook Viewer. Retrieved December 20, 2017.", "source_name": "Unit 42 Playbook Dec 2017", "url": "https://web.archive.org/web/20230702043312/https://pan-unit42.github.io/playbook_viewer/"}], "id": "relationship--b3981ca6-7ef0-4625-99a8-9cbec731bac9", "modified": "2026-06-13T12:07:50.836Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--eff1a885-6f90-42a1-901f-eef6e7a1905e", "spec_version": "2.1", "target_ref": "attack-pattern--a01bf75f-00b2-4568-a58f-565ff9bf202b", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-23013', 0, 64, '09-mitre-attack', 'retrieved', '7AA840EB40A4352A7B1F19F12C93450F7C7951723D83283B82B6B6CDFDA82407', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
