VALUES ('doc-09-mitre-attack-p0-23044', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2021-09-14T03:13:16.466Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[OSX/Shlayer](https://attack.mitre.org/software/S0402) has used the mktemp utility to make random and unique filenames for payloads, such as export tmpDir=\"$(mktemp -d /tmp/XXXXXXXXXXXX)\" or mktemp -t Installer .(Citation: sentinelone shlayer to zshlayer)(Citation: 20 macOS Common Tools and Techniques)(Citation: Shlayer jamf gatekeeper bypass 2021)", "external_references": [{"description": "Jaron Bradley. (2021, April 26). Shlayer malware abusing Gatekeeper bypass on macOS. Retrieved September 22, 2021.", "source_name": "Shlayer jamf gatekeeper bypass 2021", "url": "https://www.jamf.com/blog/shlayer-malware-abusing-gatekeeper-bypass-on-macos/"}, {"description": "Phil Stokes. (2020, September 8). Coming Out of Your Shell: From Shlayer to ZShlayer. Retrieved September 13, 2021.", "source_name": "sentinelone shlayer to zshlayer", "url": "https://www.sentinelone.com/blog/coming-out-of-your-shell-from-shlayer-to-zshlayer/"}, {"description": "Phil Stokes. (2021, February 16). 20 Common Tools & Techniques Used by macOS Threat Actors & Malware. Retrieved August 23, 2021.", "source_name": "20 macOS Common Tools and Techniques", "url": "https://labs.sentinelone.com/20-common-tools-techniques-used-by-macos-threat-actors-malware/"}], "id": "relationship--08e05216-9133-4056-bbc9-b91ea0a7c6f5", "modified": "2026-04-29T14:23:05.915Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--f1314e75-ada8-49f4-b281-b1fb8b48f2a7", "spec_version": "2.1", "target_ref": "attack-pattern--22905430-4901-4c2a-84f6-98243cb173f8", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-23044', 0, 152, '09-mitre-attack', 'retrieved', '0B01CD8E02A6F4A8F96B5D14C0D21AF349F053377DA0B38AA26A95FBB1D64521', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
