VALUES ('doc-09-mitre-attack-p0-23051', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2023-08-30T16:31:23.834Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[OSX/Shlayer](https://attack.mitre.org/software/S0402) has used the `nohup` command to instruct executed payloads to ignore hangup signals.(Citation: Shlayer jamf gatekeeper bypass 2021)", "external_references": [{"description": "Jaron Bradley. (2021, April 26). Shlayer malware abusing Gatekeeper bypass on macOS. Retrieved September 22, 2021.", "source_name": "Shlayer jamf gatekeeper bypass 2021", "url": "https://www.jamf.com/blog/shlayer-malware-abusing-gatekeeper-bypass-on-macos/"}], "id": "relationship--7a012427-6f85-45b5-b1b2-439c72f7efb4", "modified": "2026-04-29T14:23:06.092Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--f1314e75-ada8-49f4-b281-b1fb8b48f2a7", "spec_version": "2.1", "target_ref": "attack-pattern--4a2975db-414e-4c0c-bd92-775987514b4b", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-23051', 0, 74, '09-mitre-attack', 'retrieved', '2F365F94FC51A97722382E9B9872EA8B3D925D18FA35F5B9EE4B46D3E532ABDA', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
