VALUES ('doc-09-mitre-attack-p0-23054', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2022-10-04T05:00:14.930Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[OSX/Shlayer](https://attack.mitre.org/software/S0402) has used a resource fork to hide a compressed binary file of itself from the terminal, Finder, and potentially evade traditional scanners.(Citation: tau bundlore erika noerenberg 2020)(Citation: sentinellabs resource named fork 2020)", "external_references": [{"description": "Erika Noerenberg. (2020, June 29). TAU Threat Analysis: Bundlore (macOS) mm-install-macos. Retrieved October 12, 2021.", "source_name": "tau bundlore erika noerenberg 2020", "url": "https://blogs.vmware.com/security/2020/06/tau-threat-analysis-bundlore-macos-mm-install-macos.html"}, {"description": "Phil Stokes. (2020, November 5). Resourceful macOS Malware Hides in Named Fork. Retrieved October 12, 2021.", "source_name": "sentinellabs resource named fork 2020", "url": "https://www.sentinelone.com/labs/resourceful-macos-malware-hides-in-named-fork/"}], "id": "relationship--950fca51-66e4-43c6-9af0-839e962b8409", "modified": "2026-04-29T14:23:06.128Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--f1314e75-ada8-49f4-b281-b1fb8b48f2a7", "spec_version": "2.1", "target_ref": "attack-pattern--b22e5153-ac28-4cc6-865c-2054e36285cb", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-23054', 0, 112, '09-mitre-attack', 'retrieved', '5C9DB1B3CA882ED9A76BA4CAD4139C61AB5E8003F95FB81A07A8F25B4580EF34', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
