VALUES ('doc-09-mitre-attack-p0-23056', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2019-08-29T18:52:20.962Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[OSX/Shlayer](https://attack.mitre.org/software/S0402) has collected the IOPlatformUUID, session UID, and the OS version using the command sw_vers -productVersion .(Citation: Carbon Black Shlayer Feb 2019)(Citation: sentinelone shlayer to zshlayer)", "external_references": [{"description": "Carbon Black Threat Analysis Unit. (2019, February 12). New macOS Malware Variant of Shlayer (OSX) Discovered. Retrieved August 8, 2019.", "source_name": "Carbon Black Shlayer Feb 2019", "url": "https://blogs.vmware.com/security/2020/02/vmware-carbon-black-tau-threat-analysis-shlayer-macos.html"}, {"description": "Phil Stokes. (2020, September 8). Coming Out of Your Shell: From Shlayer to ZShlayer. Retrieved September 13, 2021.", "source_name": "sentinelone shlayer to zshlayer", "url": "https://www.sentinelone.com/blog/coming-out-of-your-shell-from-shlayer-to-zshlayer/"}], "id": "relationship--9db842bf-d65d-44a8-93ca-aef62cadafc1", "modified": "2026-04-29T14:23:06.140Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--f1314e75-ada8-49f4-b281-b1fb8b48f2a7", "spec_version": "2.1", "target_ref": "attack-pattern--354a7f88-63fb-41b5-a801-ce3b377b36f1", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-23056', 0, 111, '09-mitre-attack', 'retrieved', '585D9A2F52DC8FE00493B55B402A9561E11FFDAB12A4F7282F738EF0C2D98DE7', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
