VALUES ('doc-09-mitre-attack-p0-23073', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2020-06-19T20:39:21.788Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Denis](https://attack.mitre.org/software/S0354) used the IsDebuggerPresent , OutputDebugString , and SetLastError APIs to avoid debugging. [Denis](https://attack.mitre.org/software/S0354) used GetProcAddress and LoadLibrary to dynamically resolve APIs. [Denis](https://attack.mitre.org/software/S0354) also used the Wow64SetThreadContext API as part of a process hollowing process.(Citation: Cybereason Cobalt Kitty 2017)\t", "external_references": [{"description": "Dahan, A. (2017). Operation Cobalt Kitty. Retrieved December 27, 2018.", "source_name": "Cybereason Cobalt Kitty 2017", "url": "https://cdn2.hubspot.net/hubfs/3354902/Cybereason%20Labs%20Analysis%20Operation%20Cobalt%20Kitty.pdf"}], "id": "relationship--a51caaf6-3b9d-4953-9850-bf9217877644", "modified": "2026-04-29T14:23:06.150Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--f25aab1a-0cef-4910-a85d-bb38b32ea41a", "spec_version": "2.1", "target_ref": "attack-pattern--391d824f-0ef1-47a0-b0ee-c59a75e27670", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-23073', 0, 87, '09-mitre-attack', 'retrieved', 'BBB7421CBED26C7CB7502EAA311A02C4E32FE62A167EE16EB3A423CCF5E833B8', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
