VALUES ('doc-09-mitre-attack-p0-23095', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2024-05-22T21:39:38.982Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[DEADWOOD](https://attack.mitre.org/software/S1134) contains an embedded, AES-encrypted payload labeled METADATA that provides configuration information for follow-on execution.(Citation: SentinelOne Agrius 2021)", "external_references": [{"description": "Amitai Ben & Shushan Ehrlich. (2021, May). From Wiper to Ransomware: The Evolution of Agrius. Retrieved May 21, 2024.", "source_name": "SentinelOne Agrius 2021", "url": "https://assets.sentinelone.com/sentinellabs/evol-agrius"}], "id": "relationship--3dc04b05-16d3-445a-98b6-e3f3f4a352ef", "modified": "2026-04-29T14:23:06.009Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--f2e6af17-3828-4f10-88e7-343591618ddb", "spec_version": "2.1", "target_ref": "attack-pattern--0533ab23-3f7d-463f-9bd8-634d27e4dee1", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-23095', 0, 74, '09-mitre-attack', 'retrieved', '23026B361E499B201809A1FC4009CDCD041CE03FCD1FCA648E3A31DF03788368', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
