VALUES ('doc-09-mitre-attack-p0-23099', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2024-05-22T21:36:59.258Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[DEADWOOD](https://attack.mitre.org/software/S1134) can be executed as a service using various names, such as ScDeviceEnums .(Citation: SentinelOne Agrius 2021)", "external_references": [{"description": "Amitai Ben & Shushan Ehrlich. (2021, May). From Wiper to Ransomware: The Evolution of Agrius. Retrieved May 21, 2024.", "source_name": "SentinelOne Agrius 2021", "url": "https://assets.sentinelone.com/sentinellabs/evol-agrius"}], "id": "relationship--927a3c20-7d5c-42ac-97c8-e3546a11c411", "modified": "2026-04-29T14:23:06.125Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--f2e6af17-3828-4f10-88e7-343591618ddb", "spec_version": "2.1", "target_ref": "attack-pattern--f1951e8a-500e-4a26-8803-76d95c4554b4", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-23099', 0, 73, '09-mitre-attack', 'retrieved', '9F0DD7507067E042D83A1E9F5EC2D382AD355D6AA1C555E582CC424471311456', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
