INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-09-mitre-attack-p0-23103', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2024-05-22T21:58:09.981Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[DEADWOOD](https://attack.mitre.org/software/S1134) opens and writes zeroes to the first 512 bytes of each drive, deleting the MBR. [DEADWOOD](https://attack.mitre.org/software/S1134) then sends the control code IOCTL_DISK_DELETE_DRIVE_LAYOUT to ensure the MBR is removed from the drive.(Citation: SentinelOne Agrius 2021)", "external_references": [{"description": "Amitai Ben & Shushan Ehrlich. (2021, May). From Wiper to Ransomware: The Evolution of Agrius. Retrieved May 21, 2024.", "source_name": "SentinelOne Agrius 2021", "url": "https://assets.sentinelone.com/sentinellabs/evol-agrius"}], "id": "relationship--d9297dfb-9b0b-421d-a5f6-05619c778953", "modified": "2026-04-29T14:23:06.222Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--f2e6af17-3828-4f10-88e7-343591618ddb", "spec_version": "2.1", "target_ref": "attack-pattern--0af0ca99-357d-4ba1-805f-674fdfb7bef9", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-23103', 0, 91, '09-mitre-attack', 'retrieved', 'A8D79FC9BEA6420DE0416D38FBA1B647C6665F25CB0C5003DB32F21B55770D56', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
