VALUES ('doc-09-mitre-attack-p0-23104', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2024-08-28T14:16:00.768Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[GLOOXMAIL](https://attack.mitre.org/software/S0026) communicates to servers operated by Google using the Jabber/XMPP protocol for C2.(Citation: Mandiant APT1 Appendix)", "external_references": [{"description": "Mandiant. (n.d.). Appendix C (Digital) - The Malware Arsenal. Retrieved July 18, 2016.", "source_name": "Mandiant APT1 Appendix", "url": "https://www.mandiant.com/sites/default/files/2021-09/mandiant-apt1-report.pdf"}], "id": "relationship--b54e646d-a532-49e8-bcb1-d987a15cc1d9", "modified": "2026-04-29T14:23:06.173Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--f2e8c7a1-cae1-45c4-baf0-6f21bdcbb2c2", "spec_version": "2.1", "target_ref": "attack-pattern--241f9ea8-f6ae-4f38-92f5-cef5b7e539dd", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-23104', 0, 66, '09-mitre-attack', 'retrieved', '1A9E1B77276D20CA41853DEC5A505460E28C4472BE3EAD114D03EC74A0DEDD2D', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
