VALUES ('doc-09-mitre-attack-p0-23111', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2021-10-06T02:04:09.775Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Dok](https://attack.mitre.org/software/S0281) exfiltrates logs of its execution stored in the /tmp folder over FTP using the curl command.(Citation: hexed osx.dok analysis 2019) ", "external_references": [{"description": "fluffybunny. (2019, July 9). OSX.Dok Analysis. Retrieved November 17, 2024.", "source_name": "hexed osx.dok analysis 2019", "url": "https://web.archive.org/web/20221007144948/http://www.hexed.in/2019/07/osxdok-analysis.html"}], "id": "relationship--96667f6c-e625-4696-92b5-d65d142b3f43", "modified": "2026-04-29T14:23:06.130Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--f36b2598-515f-4345-84e5-5ccde253edbe", "spec_version": "2.1", "target_ref": "attack-pattern--fb8d023d-45be-47e9-bc51-f56bcae6435b", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-23111', 0, 70, '09-mitre-attack', 'retrieved', '4871334CA52BB06B6726533E18338DF5EFC71B658598DE661D57F13DD9F7906F', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
