VALUES ('doc-09-mitre-attack-p0-23112', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2018-10-17T00:14:20.652Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Dok](https://attack.mitre.org/software/S0281) installs a root certificate to aid in [Adversary-in-the-Middle](https://attack.mitre.org/techniques/T1557) actions using the command add-trusted-cert -d -r trustRoot -k /Library/Keychains/System.keychain /tmp/filename .(Citation: objsee mac malware 2017)(Citation: hexed osx.dok analysis 2019)", "external_references": [{"description": "fluffybunny. (2019, July 9). OSX.Dok Analysis. Retrieved November 17, 2024.", "source_name": "hexed osx.dok analysis 2019", "url": "https://web.archive.org/web/20221007144948/http://www.hexed.in/2019/07/osxdok-analysis.html"}, {"description": "Patrick Wardle. (n.d.). Mac Malware of 2017. Retrieved September 21, 2018.", "source_name": "objsee mac malware 2017", "url": "https://objective-see.com/blog/blog_0x25.html"}], "id": "relationship--97c225e6-64ad-42af-8cc4-4fb4deea39fc", "modified": "2026-04-29T14:23:06.132Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--f36b2598-515f-4345-84e5-5ccde253edbe", "spec_version": "2.1", "target_ref": "attack-pattern--c615231b-f253-4f58-9d47-d5b4cbdb6839", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-23112', 0, 96, '09-mitre-attack', 'retrieved', '505F69160266F0021A398754A6CDCD0C3544C58488A412223EAD23AC83299D31', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
