VALUES ('doc-09-mitre-attack-p0-23144', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2021-06-07T13:41:57.699Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "The [FIVEHANDS](https://attack.mitre.org/software/S0618) payload is encrypted with AES-128.(Citation: FireEye FiveHands April 2021)(Citation: CISA AR21-126A FIVEHANDS May 2021)(Citation: NCC Group Fivehands June 2021)", "external_references": [{"description": "CISA. (2021, May 6). Analysis Report (AR21-126A) FiveHands Ransomware. Retrieved June 7, 2021.", "source_name": "CISA AR21-126A FIVEHANDS May 2021", "url": "https://us-cert.cisa.gov/ncas/analysis-reports/ar21-126a"}, {"description": "Matthews, M. and Backhouse, W. (2021, June 15). Handy guide to a new Fivehands ransomware variant. Retrieved June 24, 2021.", "source_name": "NCC Group Fivehands June 2021", "url": "https://research.nccgroup.com/2021/06/15/handy-guide-to-a-new-fivehands-ransomware-variant/"}, {"description": "McLellan, T. and Moore, J. et al. (2021, April 29). UNC2447 SOMBRAT and FIVEHANDS Ransomware: A Sophisticated Financial Threat. Retrieved June 2, 2021.", "source_name": "FireEye FiveHands April 2021", "url": "https://www.fireeye.com/blog/threat-research/2021/04/unc2447-sombrat-and-fivehands-ransomware-sophisticated-financial-threat.html"}], "id": "relationship--ba97fa9c-949b-4e86-b537-e828b602e39f", "modified": "2026-04-29T14:23:06.179Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--f464354c-7103-47c6-969b-8766f0157ed2", "spec_version": "2.1", "target_ref": "attack-pattern--0d91b3c0-5e50-47c3-949a-2a796f04d144", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-23144', 0, 133, '09-mitre-attack', 'retrieved', 'F0B613A9AD2D8FEF5923EEA