VALUES ('doc-09-mitre-attack-p0-23208', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-01T19:18:54.720Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Lizar](https://attack.mitre.org/software/S0681) has obfuscated the fingerprint of the victim system, the local IP address, and the Fowler-Noll-V 1 (FNV-1) hash of the local IP address using an XOR operation. The data is then sent to the C2 server.(Citation: SekoiaBourhis_DiceLoader_Feb2024) ", "external_references": [{"description": "Bourhis, P., Sekoia TDR. (2024, February 1). Unveiling the intricacies of DiceLoader. Retrieved May 14, 2025.", "source_name": "SekoiaBourhis_DiceLoader_Feb2024", "url": "https://blog.sekoia.io/unveiling-the-intricacies-of-diceloader/"}], "id": "relationship--451a9d37-4e16-4822-85db-821b1dd49ddc", "modified": "2026-04-29T14:23:06.020Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--f74a5069-015d-4404-83ad-5ca01056c0dc", "spec_version": "2.1", "target_ref": "attack-pattern--b3d682b6-98f2-4fb0-aa3b-b4df007ca70a", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-23208', 0, 90, '09-mitre-attack', 'retrieved', '21451CECD8CEABA5BE4DE7EF860855A9E958CF8292B66C4751AEBE881A29D793', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
