VALUES ('doc-09-mitre-attack-p0-23265', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2024-02-07T19:19:22.413Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[SLOWPULSE](https://attack.mitre.org/software/S1104) can modify LDAP and two factor authentication flows by inspecting login credentials and forcing successful authentication if the provided password matches a chosen backdoor password.(Citation: Mandiant Pulse Secure Zero-Day April 2021)", "external_references": [{"description": "Perez, D. et al. (2021, April 20). Check Your Pulse: Suspected APT Actors Leverage Authentication Bypass Techniques and Pulse Secure Zero-Day. Retrieved February 5, 2024.", "source_name": "Mandiant Pulse Secure Zero-Day April 2021", "url": "https://www.mandiant.com/resources/blog/suspected-apt-actors-leverage-bypass-techniques-pulse-secure-zero-day"}], "id": "relationship--0117960a-178b-41f8-b7c1-5a4852be582a", "modified": "2026-04-29T14:23:05.904Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--f8fc98ac-ad6d-44db-b6e2-f0c6eb4eace4", "spec_version": "2.1", "target_ref": "attack-pattern--fa44a152-ac48-441e-a524-dd7b04b8adcd", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-23265', 0, 97, '09-mitre-attack', 'retrieved', '10F3EDF40FF2B6AA59036DBE8B4B31B6B0CB2AD799836D452499435B8F22A030', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
