VALUES ('doc-09-mitre-attack-p0-23266', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2024-03-18T20:13:09.075Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[SLOWPULSE](https://attack.mitre.org/software/S1104) can log credentials on compromised Pulse Secure VPNs during the `DSAuth::AceAuthServer::checkUsernamePassword`ACE-2FA authentication procedure.(Citation: Mandiant Pulse Secure Zero-Day April 2021)", "external_references": [{"description": "Perez, D. et al. (2021, April 20). Check Your Pulse: Suspected APT Actors Leverage Authentication Bypass Techniques and Pulse Secure Zero-Day. Retrieved February 5, 2024.", "source_name": "Mandiant Pulse Secure Zero-Day April 2021", "url": "https://www.mandiant.com/resources/blog/suspected-apt-actors-leverage-bypass-techniques-pulse-secure-zero-day"}], "id": "relationship--0154e3ae-8ccc-4ebb-a14b-2305d9212651", "modified": "2026-04-29T14:23:05.904Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--f8fc98ac-ad6d-44db-b6e2-f0c6eb4eace4", "spec_version": "2.1", "target_ref": "attack-pattern--dd43c543-bb85-4a6f-aa6e-160d90d06a49", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-23266', 0, 85, '09-mitre-attack', 'retrieved', '34322BDE5164F531068FD9D26FFADEF3806F48EED564E21855A147C6622E0EF4', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
