VALUES ('doc-09-mitre-attack-p0-23274', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2020-05-18T21:01:51.381Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[LoudMiner](https://attack.mitre.org/software/S0451) used the ps command to monitor the running processes on the system.(Citation: ESET LoudMiner June 2019)\t", "external_references": [{"description": "Malik, M. (2019, June 20). LoudMiner: Cross-platform mining in cracked VST software. Retrieved May 18, 2020.", "source_name": "ESET LoudMiner June 2019", "url": "https://www.welivesecurity.com/2019/06/20/loudminer-mining-cracked-vst-software/"}], "id": "relationship--1232c797-ebf4-4036-9ebb-a65fbe8b1443", "modified": "2026-04-29T14:23:05.929Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--f99f3dcc-683f-4936-8791-075ac5e58f10", "spec_version": "2.1", "target_ref": "attack-pattern--8f4a33ec-8b1f-4b80-a2f6-642b2e479580", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-23274', 0, 71, '09-mitre-attack', 'retrieved', '895AC4AACA60EDEE009D480A04E285E4CD9CA226724702517E78B325A67A7241', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
