VALUES ('doc-09-mitre-attack-p0-23275', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2020-05-18T21:01:51.371Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[LoudMiner](https://attack.mitre.org/software/S0451) launched the QEMU services in the /Library/LaunchDaemons/ folder using launchctl . It also uses launchctl to unload all [Launch Daemon](https://attack.mitre.org/techniques/T1543/004)s when updating to a newer version of [LoudMiner](https://attack.mitre.org/software/S0451).(Citation: ESET LoudMiner June 2019)\t", "external_references": [{"description": "Malik, M. (2019, June 20). LoudMiner: Cross-platform mining in cracked VST software. Retrieved May 18, 2020.", "source_name": "ESET LoudMiner June 2019", "url": "https://www.welivesecurity.com/2019/06/20/loudminer-mining-cracked-vst-software/"}], "id": "relationship--131d75f1-84c3-4ef8-b858-7f74aa7ce157", "modified": "2026-04-29T14:23:05.930Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--f99f3dcc-683f-4936-8791-075ac5e58f10", "spec_version": "2.1", "target_ref": "attack-pattern--810aa4ad-61c9-49cb-993f-daa06199421d", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-23275', 0, 87, '09-mitre-attack', 'retrieved', '290BCE3B9D03C3302D72A1EC562685FB65F78B98233D33CD6466A239EB1435B4', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
