VALUES ('doc-09-mitre-attack-p0-23280', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2020-05-18T21:01:51.369Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[LoudMiner](https://attack.mitre.org/software/S0451) adds plist files with the naming format com.[random_name].plist in the /Library/LaunchDaemons folder with the RunAtLoad and KeepAlive keys set to true .(Citation: ESET LoudMiner June 2019)", "external_references": [{"description": "Malik, M. (2019, June 20). LoudMiner: Cross-platform mining in cracked VST software. Retrieved May 18, 2020.", "source_name": "ESET LoudMiner June 2019", "url": "https://www.welivesecurity.com/2019/06/20/loudminer-mining-cracked-vst-software/"}], "id": "relationship--7398839c-3feb-4162-a3d2-dda8fc2f0375", "modified": "2026-04-29T14:23:06.083Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--f99f3dcc-683f-4936-8791-075ac5e58f10", "spec_version": "2.1", "target_ref": "attack-pattern--573ad264-1371-4ae0-8482-d2673b719dba", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-23280', 0, 81, '09-mitre-attack', 'retrieved', '0B350AB4F5AA1C5CF4E1F6D035A7C6FD9A234EBE417545FFE507BF7FE1CE3716', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
