VALUES ('doc-09-mitre-attack-p0-23281', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2020-05-18T21:01:51.374Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[LoudMiner](https://attack.mitre.org/software/S0451) harvested system resources to mine cryptocurrency, using XMRig to mine Monero.(Citation: ESET LoudMiner June 2019)\t", "external_references": [{"description": "Malik, M. (2019, June 20). LoudMiner: Cross-platform mining in cracked VST software. Retrieved May 18, 2020.", "source_name": "ESET LoudMiner June 2019", "url": "https://www.welivesecurity.com/2019/06/20/loudminer-mining-cracked-vst-software/"}], "id": "relationship--774302ff-3ab9-4328-a434-6188efe0928a", "modified": "2026-04-29T14:23:06.088Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--f99f3dcc-683f-4936-8791-075ac5e58f10", "spec_version": "2.1", "target_ref": "attack-pattern--a718a0c8-5768-41a1-9958-a1cc3f995e99", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-23281', 0, 70, '09-mitre-attack', 'retrieved', '96AB5B3367E79EE458860972FCD4C3950ED5E50F8FB875E5C49BDF0F40A907AB', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
