VALUES ('doc-09-mitre-attack-p0-23309', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2021-02-08T23:18:31.759Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[BitPaymer](https://attack.mitre.org/software/S0570) compares file names and paths to a list of excluded names and directory names during encryption.(Citation: Crowdstrike Indrik November 2018)", "external_references": [{"description": "Frankoff, S., Hartley, B. (2018, November 14). Big Game Hunting: The Evolution of INDRIK SPIDER From Dridex Wire Fraud to BitPaymer Targeted Ransomware. Retrieved January 6, 2021.", "source_name": "Crowdstrike Indrik November 2018", "url": "https://www.crowdstrike.com/blog/big-game-hunting-the-evolution-of-indrik-spider-from-dridex-wire-fraud-to-bitpaymer-targeted-ransomware/"}], "id": "relationship--1cc1c2b0-5fb8-420e-8285-db4616a9fab2", "modified": "2026-04-29T14:23:05.944Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--fa766a65-5136-4ff3-8429-36d08eaa0100", "spec_version": "2.1", "target_ref": "attack-pattern--853c4192-4311-43e1-bfbb-b11b14911852", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-23309', 0, 86, '09-mitre-attack', 'retrieved', 'E62AEBDB01C79F7DDB080A82E36ADDA5BBD700001A10CB8C919C68A4F3CF76AE', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
