VALUES ('doc-09-mitre-attack-p0-23320', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2021-02-08T23:18:31.896Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[BitPaymer](https://attack.mitre.org/software/S0570) can suppress UAC prompts by setting the HKCU\\Software\\Classes\\ms-settings\\shell\\open\\command registry key on Windows 10 or HKCU\\Software\\Classes\\mscfile\\shell\\open\\command on Windows 7 and launching the eventvwr.msc process, which launches [BitPaymer](https://attack.mitre.org/software/S0570) with elevated privileges.(Citation: Crowdstrike Indrik November 2018)", "external_references": [{"description": "Frankoff, S., Hartley, B. (2018, November 14). Big Game Hunting: The Evolution of INDRIK SPIDER From Dridex Wire Fraud to BitPaymer Targeted Ransomware. Retrieved January 6, 2021.", "source_name": "Crowdstrike Indrik November 2018", "url": "https://www.crowdstrike.com/blog/big-game-hunting-the-evolution-of-indrik-spider-from-dridex-wire-fraud-to-bitpaymer-targeted-ransomware/"}], "id": "relationship--a1862cc9-ba25-4d48-b2d5-55781dd1fa3e", "modified": "2026-04-29T14:23:06.145Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--fa766a65-5136-4ff3-8429-36d08eaa0100", "spec_version": "2.1", "target_ref": "attack-pattern--120d5519-3098-4e1c-9191-2aa61232f073", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-23320', 0, 99, '09-mitre-attack', 'retrieved', '8A31A978C09C6C3E5471393C1F976CF7A2A67DA604D2989A0A13C6A4C42C8504', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
