VALUES ('doc-09-mitre-attack-p0-23337', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2017-12-14T16:46:06.044Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[BACKSPACE](https://attack.mitre.org/software/S0031) attempts to avoid detection by checking a first stage command and control server to determine if it should connect to the second stage server, which performs \"louder\" interactions with the malware.(Citation: FireEye APT30)", "external_references": [{"description": "FireEye Labs. (2015, April). APT30 AND THE MECHANICS OF A LONG-RUNNING CYBER ESPIONAGE OPERATION. Retrieved November 17, 2024.", "source_name": "FireEye APT30", "url": "https://media.kasperskycontenthub.com/wp-content/uploads/sites/43/2015/05/20081935/rpt-apt30.pdf"}], "id": "relationship--a6962782-1942-42f5-a627-f205376e2ec2", "modified": "2026-04-29T14:23:06.152Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--fb261c56-b80e-43a9-8351-c84081e7213d", "spec_version": "2.1", "target_ref": "attack-pattern--84e02621-8fdf-470f-bd58-993bb6a89d91", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-23337', 0, 88, '09-mitre-attack', 'retrieved', '8F59DE8CCF3BF2520CD047B6800C16A23567D7AA2D190F9DA7396A3A5369D8FE', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
