VALUES ('doc-09-mitre-attack-p0-23417', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2021-12-27T19:19:42.756Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[WarzoneRAT](https://attack.mitre.org/software/S0670) can add itself to the `HKCU\\Software\\Microsoft\\Windows\\CurrentVersion\\Run` and `HKCU\\Software\\Microsoft\\Windows\\CurrentVersion\\Explorer\\UIF2IS20VK` Registry keys.(Citation: Check Point Warzone Feb 2020)", "external_references": [{"description": "Harakhavik, Y. (2020, February 3). Warzone: Behind the enemy lines. Retrieved December 17, 2021.", "source_name": "Check Point Warzone Feb 2020", "url": "https://research.checkpoint.com/2020/warzone-behind-the-enemy-lines/"}], "id": "relationship--0f90920b-ab2e-4c79-95a5-5438c172a46d", "modified": "2026-04-29T14:23:05.925Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--fde19a18-e502-467f-be14-58c71b4e7f4b", "spec_version": "2.1", "target_ref": "attack-pattern--9efb1ea7-c37b-4595-9640-b7680cd84279", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-23417', 0, 69, '09-mitre-attack', 'retrieved', 'BBC8FC57889F96C93BE9C6F7804B1D1471B4000CDC69225F8D8B2EB8146D8AE4', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
