VALUES ('doc-09-mitre-attack-p0-23422', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2021-12-27T19:19:42.888Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[WarzoneRAT](https://attack.mitre.org/software/S0670) can use `sdclt.exe` to bypass UAC in Windows 10 to escalate privileges; for older Windows versions [WarzoneRAT](https://attack.mitre.org/software/S0670) can use the IFileOperation exploit to bypass the UAC module.(Citation: Check Point Warzone Feb 2020)(Citation: Uptycs Warzone UAC Bypass November 2020)", "external_references": [{"description": "Harakhavik, Y. (2020, February 3). Warzone: Behind the enemy lines. Retrieved December 17, 2021.", "source_name": "Check Point Warzone Feb 2020", "url": "https://research.checkpoint.com/2020/warzone-behind-the-enemy-lines/"}, {"description": "Mohanta, A. (2020, November 25). Warzone RAT comes with UAC bypass technique. Retrieved April 7, 2022.", "source_name": "Uptycs Warzone UAC Bypass November 2020", "url": "https://www.uptycs.com/blog/warzone-rat-comes-with-uac-bypass-technique"}], "id": "relationship--26fd5ea0-6f63-4c0a-9a84-23e489c1161c", "modified": "2026-04-29T14:23:05.958Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--fde19a18-e502-467f-be14-58c71b4e7f4b", "spec_version": "2.1", "target_ref": "attack-pattern--120d5519-3098-4e1c-9191-2aa61232f073", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-23422', 0, 118, '09-mitre-attack', 'retrieved', 'D1CE7979083937592A9DA9529458F39CDAD0BF1B89A4231FB6B764A79B2ABD50', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
