VALUES ('doc-09-mitre-attack-p0-23429', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2022-04-07T15:24:55.474Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[WarzoneRAT](https://attack.mitre.org/software/S0670) can create `HKCU\\Software\\Classes\\Folder\\shell\\open\\command` as a new registry key during privilege escalation.(Citation: Uptycs Warzone UAC Bypass November 2020)(Citation: Check Point Warzone Feb 2020) ", "external_references": [{"description": "Harakhavik, Y. (2020, February 3). Warzone: Behind the enemy lines. Retrieved December 17, 2021.", "source_name": "Check Point Warzone Feb 2020", "url": "https://research.checkpoint.com/2020/warzone-behind-the-enemy-lines/"}, {"description": "Mohanta, A. (2020, November 25). Warzone RAT comes with UAC bypass technique. Retrieved April 7, 2022.", "source_name": "Uptycs Warzone UAC Bypass November 2020", "url": "https://www.uptycs.com/blog/warzone-rat-comes-with-uac-bypass-technique"}], "id": "relationship--42a2aec6-4efb-44d0-8ae8-32a208c05da6", "modified": "2026-04-29T14:23:06.016Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--fde19a18-e502-467f-be14-58c71b4e7f4b", "spec_version": "2.1", "target_ref": "attack-pattern--57340c81-c025-4189-8fa0-fc7ede51bae4", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-23429', 0, 103, '09-mitre-attack', 'retrieved', '221D4C996E385A5EAA0E4011A23711023F6E5B5FCD93C6D7048F34B11D590FE7', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
