VALUES ('doc-09-mitre-attack-p0-23430', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2021-12-27T19:19:42.770Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[WarzoneRAT](https://attack.mitre.org/software/S0670) can perform COM hijacking by setting the path to itself to the `HKCU\\Software\\Classes\\Folder\\shell\\open\\command` key with a `DelegateExecute` parameter.(Citation: Check Point Warzone Feb 2020)", "external_references": [{"description": "Harakhavik, Y. (2020, February 3). Warzone: Behind the enemy lines. Retrieved December 17, 2021.", "source_name": "Check Point Warzone Feb 2020", "url": "https://research.checkpoint.com/2020/warzone-behind-the-enemy-lines/"}], "id": "relationship--581061d3-6216-4a58-aa46-3640d8e94b02", "modified": "2026-04-29T14:23:06.045Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--fde19a18-e502-467f-be14-58c71b4e7f4b", "spec_version": "2.1", "target_ref": "attack-pattern--bc0f5e80-91c0-4e04-9fbb-e4e332c85dae", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-23430', 0, 77, '09-mitre-attack', 'retrieved', '00F2423C8C5BDB7AD427BC6205FE2E73549219B737033943D52FE9EDF413A388', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
